        vm.startPrank(owner);
        token = new PresidentsSquidGame();
        token.setRewardAddress(rewardAddress);
        token.excludeFromFees(rewardAddress, true);  // Ensure reward address is excluded
        token.setSellFee(5);  // 5% sell fee
        token.setIsTradingEnabled(true);
        token.transfer(user1, initialAmount);
        vm.stopPrank();
    }

    function testAccountingVulnerability() public {
        // Pre-transfer balances
        uint256 initialRewardBalance = token.balanceOf(rewardAddress);
        uint256 transferAmount = token.balanceOf(user1);

        vm.startPrank(user1);
        // Simulate sell transaction (transfer to AMM pair)
        token.transfer(ammPair, transferAmount);
        vm.stopPrank();

        // Post-transfer balances
        uint256 expectedFee = transferAmount * 5 / 100; // 5% fee
        uint256 expectedNetAmount = transferAmount - expectedFee;

        // Check balances
        assertEq(token.balanceOf(user1), 0, "Sender balance incorrect");
        assertEq(
            token.balanceOf(ammPair), 
            expectedNetAmount, 
            "Recipient received incorrect amount"
        );
        assertEq(
            token.balanceOf(rewardAddress),
            initialRewardBalance + expectedFee,
            "Fee allocation incorrect"
        );

        // Total supply consistency check
        uint256 totalSupply = token.totalSupply();
        uint256 balanceSum = token.balanceOf(owner) + 
                            token.balanceOf(user1) + 
                            token.balanceOf(ammPair) + 
                            token.balanceOf(rewardAddress);

        assertEq(
            balanceSum,
            totalSupply,
            "Sum of balances should equal total supply"
        );
    }
}
